<div class="d-flex flex-wrap gap-2 mb-3"><h2 class="h4">优惠码</h2><div class="ms-auto"><a class="btn btn-primary" href="<?= h(url_to('admin/coupon/edit')) ?>">新增</a> <a class="btn btn-outline-primary" href="<?= h(url_to('admin/coupon/batch')) ?>">批量生成</a></div></div>
<form class="row g-2 mb-3"><div class="col-md-4"><input class="form-control" name="kw" value="<?= h($kw) ?>" placeholder="代码或名称"></div><div class="col-md-3"><select class="form-select" name="status"><option value="">全部状态</option><option value="1" <?= $status === '1' ? 'selected' : '' ?>>启用</option><option value="0" <?= $status === '0' ? 'selected' : '' ?>>停用</option></select></div><div class="col-auto"><button class="btn btn-outline-secondary">筛选</button></div></form>
<div class="table-responsive table-card"><table class="table table-hover"><thead><tr><th>代码</th><th>名称</th><th>类型/值</th><th>场景</th><th>使用/预留/上限</th><th>时间窗口</th><th>状态</th><th>操作</th></tr></thead><tbody><?php foreach ($list as $r): ?><tr><td class="mono"><?= h($r['code']) ?></td><td><?= h($r['name']) ?></td><td><?= h($r['type'] === 'percent' ? '百分比' : '固定') ?> <?= h($r['value']) ?></td><td><?= h($r['scenes']) ?></td><td><?= h($r['used_count'] . ' / ' . $r['reserved_count'] . ' / ' . ($r['total_limit'] ?: '不限')) ?></td><td><?= h(($r['start_time'] ? fmt_time($r['start_time']) : '立即') . ' - ' . ($r['end_time'] ? fmt_time($r['end_time']) : '不限')) ?></td><td><span class="badge bg-<?= $r['status'] ? 'success' : 'secondary' ?>"><?= $r['status'] ? '启用' : '停用' ?></span></td><td class="text-nowrap"><a class="btn btn-sm btn-outline-primary" href="<?= h(url_to('admin/coupon/edit', ['id' => $r['id']])) ?>">编辑</a> <a class="btn btn-sm btn-outline-info" href="<?= h(url_to('admin/coupon/detail', ['id' => $r['id']])) ?>">详情</a><form class="d-inline" method="post" action="<?= h(url_to('admin/coupon/toggle')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= h($r['id']) ?>"><input type="hidden" name="status" value="<?= $r['status'] ? 0 : 1 ?>"><button class="btn btn-sm btn-outline-secondary"><?= $r['status'] ? '停用' : '启用' ?></button></form><form class="d-inline" method="post" action="<?= h(url_to('admin/coupon/delete')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= h($r['id']) ?>"><button class="btn btn-sm btn-outline-danger" data-confirm="确定删除？">删除</button></form></td></tr><?php endforeach; ?></tbody></table></div><?= pager_html($total, $page, $size, ['kw' => $kw, 'status' => $status]) ?>